+        }
+        if (!empty($filters['status'])) {
+            $where[] = 'q.status = :status';
+            $params['status'] = (string) $filters['status'];
+        }
+        if (!empty($filters['tag'])) {
+            $where[] = 'EXISTS (SELECT 1 FROM question_tag_map qtm WHERE qtm.question_id = q.id AND qtm.tag_id = :tag)';
