+        }
+
+        $this->connection->update('questions', [
+            'status' => 'PUBLISHED',
+            'updated_at' => (new \DateTimeImmutable())->format('Y-m-d H:i:s'),
+            'duplicate_acknowledged' => 1,
+        ], ['id' => $id]);
+
+        return ['published' => true, 'warnings' => $flags];
+    }
+
+    public function changeStatus(int $id, string $status): array
