+            'status' => $question['status'],
+            'category' => ['id' => (int) $question['category_id'], 'name' => $question['category_name']],
+            'tags' => $tags,
+            'created_at' => $question['created_at'],
+            'updated_at' => $question['updated_at'],
+            'current_version' => $version,
+        ];
+    }
