  const load = async () => {
    const [k, t, o] = await Promise.all([
      analyticsApi.compliance(from, to, orgUnit),
      analyticsApi.trend('credential_submissions', from, to, 'daily'),
      analyticsApi.listOrgUnits(),
    ]);
    setKpis(k.data || {});
    setTrend(t.data.points || []);
    setOrgUnits(o.data.items || []);
