                  <QuestionTagsPage />
                </RoleGuard>
              }
            />
            <Route
              path="/admin/firms"
              element={
                <RoleGuard allowedRoles={['ROLE_SYSTEM_ADMIN']}>
                  <FirmManagementPage />
                </RoleGuard>
              }
            />
            <Route
              path="/practitioners"
              element={
                <RoleGuard allowedRoles={['ROLE_USER']}>
                  <PractitionerListPage />
                </RoleGuard>
