+        for ($i = 1; $i <= 4; $i++) {
+            $db->executeStatement('UPDATE credential_submissions SET current_state = :s, updated_at = :u WHERE id = :id', ['s' => 'REJECTED', 'u' => (new \DateTimeImmutable())->format('Y-m-d H:i:s'), 'id' => $i]);
+        }
+        $alerts->checkRejectedCredentialsForFirm(1);
+        self::assertSame(0, (int) $db->fetchOne('SELECT COUNT(*) FROM alerts'));
