+        $db->executeStatement('UPDATE practitioners SET firm_id = 1 WHERE id = (SELECT practitioner_id FROM credential_submissions WHERE id = 6)');
+        $alerts->checkRejectedCredentialsForFirm(1);
+        self::assertGreaterThanOrEqual(1, (int) $db->fetchOne("SELECT COUNT(*) FROM alerts WHERE alert_type = 'REJECTED_CREDENTIAL_SPIKE'"));
+    }
