            { label: 'INACTIVE', value: 'INACTIVE' },
            { label: 'SUSPENDED', value: 'SUSPENDED' },
          ]}
          onChange={(value) => setFilters((f) => ({ ...f, status: value || '' }))}
        />
        <Input
          placeholder="Firm ID"
          value={filters.firm_id}
